const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const canada = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Canada'))
      .geometry();

    function doyLimitForAug3(year) {
      const y0 = ee.Date.fromYMD(year, 1, 1);
      const aug3 = ee.Date.fromYMD(year, 8, 3);
      return aug3.difference(y0, 'day').add(1); // inclusive DOY
    }

    const years = [2023, 2025];
    const datasets = ['MODIS/061/MCD64A1', 'MODIS/006/MCD64A1'];

    async function datasetWorksForAllYears(ds) {
      const checks = await Promise.all(years.map(async (y) => {
        const col = ee.ImageCollection(ds)
          .filterBounds(canada)
          .filterDate(ee.Date.fromYMD(y, 1, 1), ee.Date.fromYMD(y, 9, 1));
        return await col.size().getInfo();
      }));
      // require at least some images for both years
      return checks.every(sz => (sz || 0) > 0);
    }

    let chosenDataset = null;
    for (const ds of datasets) {
      const ok = await datasetWorksForAllYears(ds);
      if (ok) {
        chosenDataset = ds;
        break;
      }
    }
    if (!chosenDataset) {
      console.log('No common dataset with images for both years in date window.');
      console.log('C1');
      return;
    }

    // Resolve burn band name (case-insensitive search) from the chosen dataset
    async function getBurnBandName(ds) {
      const bnList = await ee.ImageCollection(ds).first().bandNames().getInfo();
      if (!bnList || bnList.length === 0) return null;
      const lower = bnList.map(b => String(b).toLowerCase());
      const idx = lower.findIndex(b => b === 'burndate' || b === 'burn_date');
      return idx >= 0 ? bnList[idx] : null;
    }
    const burnBand = await getBurnBandName(chosenDataset);
    if (!burnBand) {
      console.log('Burn band not found.');
      console.log('D');
      return;
    }

    async function computeBurnedArea(year) {
      const start = ee.Date.fromYMD(year, 1, 1);
      const endIncAug = ee.Date.fromYMD(year, 9, 1); // include August
      const doyLimit = doyLimitForAug3(year);

      const col = ee.ImageCollection(chosenDataset)
        .filterBounds(canada)
        .filterDate(start, endIncAug);

      const imgCount = await col.size().getInfo();
      if (!imgCount || imgCount === 0) {
        return {status: 'C1', info: {year, imgCount: 0}};
      }

      const bdMax = col.select([burnBand]).max();

      const burnedMask = bdMax.gt(0).and(bdMax.lte(doyLimit));
      const maskBand = burnedMask.rename('mask');

      const pxCount = await maskBand.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e9,
        tileScale: 4
      }).get('mask').getInfo();

      if (pxCount === null || pxCount === 0) {
        return {status: 'C2', info: {year, imgCount, pxCount: pxCount || 0}};
      }

      const areaImg = ee.Image.pixelArea().updateMask(burnedMask).rename('area');
      const areaSumM2 = await areaImg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e9,
        tileScale: 4
      }).get('area').getInfo();

      if (areaSumM2 === null || isNaN(areaSumM2) || !isFinite(areaSumM2)) {
        return {status: 'C3', info: {year, imgCount, pxCount}};
      }

      const areaMha = areaSumM2 / 1e10; // m2 to Mha
      return {
        status: 'OK',
        year,
        imgCount,
        pxCount,
        areaMha
      };
    }

    console.log(`Dataset: ${chosenDataset} (band: ${burnBand})`);

    const res2023 = await computeBurnedArea(2023);
    if (res2023.status !== 'OK') {
      console.log(`2023 Images: ${(res2023.info && res2023.info.imgCount) || 0}`);
      console.log(res2023.status);
      return;
    }
    console.log(`2023 Images: ${res2023.imgCount}, DOY<=216, Burned px: ${res2023.pxCount}, Area Mha: ${res2023.areaMha.toFixed(2)}`);

    const res2025 = await computeBurnedArea(2025);
    if (res2025.status !== 'OK') {
      console.log(`2025 Images: ${(res2025.info && res2025.info.imgCount) || 0}`);
      console.log(res2025.status);
      return;
    }
    console.log(`2025 Images: ${res2025.imgCount}, DOY<=216, Burned px: ${res2025.pxCount}, Area Mha: ${res2025.areaMha.toFixed(2)}`);

    const greater = res2025.areaMha > res2023.areaMha;
    console.log(`Comparison: 2025 > 2023 ? ${greater ? 'true' : 'false'}`);
    console.log(greater ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : String(err)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
